import{_ as a,o as e,c as d,ag as r}from"./chunks/framework.BcZEdlUI.js";const b=JSON.parse('{"title":"AI 服务配置","description":"配置 SceneFab 所使用的 AI 服务（DeepSeek / Qwen3.7 / Edge-TTS）。","frontmatter":{"title":"AI 服务配置","description":"配置 SceneFab 所使用的 AI 服务（DeepSeek / Qwen3.7 / Edge-TTS）。"},"headers":[],"relativePath":"guide/ai-configuration.md","filePath":"guide/ai-configuration.md","lastUpdated":1780149753000}'),i={name:"guide/ai-configuration.md"};function h(s,t,l,n,o,p){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="ai-服务配置" tabindex="-1">AI 服务配置 <a class="header-anchor" href="#ai-服务配置" aria-label="Permalink to &quot;AI 服务配置&quot;">​</a></h1><p>SceneFab 支持配置多个 AI 服务商，所有配置在本地存储，绝不外传。</p><hr><h2 id="deepseek-解说稿生成" tabindex="-1">DeepSeek（解说稿生成） <a class="header-anchor" href="#deepseek-解说稿生成" aria-label="Permalink to &quot;DeepSeek（解说稿生成）&quot;">​</a></h2><h3 id="获取-api-key" tabindex="-1">获取 API Key <a class="header-anchor" href="#获取-api-key" aria-label="Permalink to &quot;获取 API Key&quot;">​</a></h3><ol><li>访问 <a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">platform.deepseek.com</a> → API Keys → Create</li><li>推荐使用 <strong>DeepSeek-V4</strong> 模型（性价比最高）</li></ol><h3 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to &quot;配置项&quot;">​</a></h3><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td>API Key</td><td>你的 DeepSeek API Key</td><td>—</td></tr><tr><td>模型</td><td>DeepSeek-V4 / DeepSeek-Coder</td><td>DeepSeek-V4</td></tr><tr><td>Base URL</td><td>API 端点</td><td><a href="https://api.deepseek.com" target="_blank" rel="noreferrer">https://api.deepseek.com</a></td></tr><tr><td>Max Tokens</td><td>单次最大输出</td><td>4096</td></tr><tr><td>Temperature</td><td>创造性（0=确定输出，1=最大随机）</td><td>0.7</td></tr></tbody></table><h3 id="费用估算" tabindex="-1">费用估算 <a class="header-anchor" href="#费用估算" aria-label="Permalink to &quot;费用估算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>tokens 消耗</th><th>费用</th></tr></thead><tbody><tr><td>5 分钟视频解说生成</td><td>~50K tokens</td><td>~0.05 元</td></tr><tr><td>2 小时电影解说生成</td><td>~500K tokens</td><td>~0.5 元</td></tr></tbody></table><hr><h2 id="qwen3-7-视频语义分析" tabindex="-1">Qwen3.7（视频语义分析） <a class="header-anchor" href="#qwen3-7-视频语义分析" aria-label="Permalink to &quot;Qwen3.7（视频语义分析）&quot;">​</a></h2><h3 id="获取-api-key-1" tabindex="-1">获取 API Key <a class="header-anchor" href="#获取-api-key-1" aria-label="Permalink to &quot;获取 API Key&quot;">​</a></h3><ol><li>访问 <a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">阿里云百炼</a> → API Keys → 创建</li><li>选择 <code>qwen3.7-max</code> 模型</li></ol><h3 id="配置项-1" tabindex="-1">配置项 <a class="header-anchor" href="#配置项-1" aria-label="Permalink to &quot;配置项&quot;">​</a></h3><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td>API Key</td><td>你的阿里云 API Key</td><td>—</td></tr><tr><td>模型</td><td>qwen3.7-max / qwen3.7-plus</td><td>qwen3.7-max</td></tr><tr><td>Base URL</td><td>API 端点</td><td><a href="https://dashscope.aliyuncs.com" target="_blank" rel="noreferrer">https://dashscope.aliyuncs.com</a></td></tr></tbody></table><h3 id="费用估算-1" tabindex="-1">费用估算 <a class="header-anchor" href="#费用估算-1" aria-label="Permalink to &quot;费用估算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>调用次数</th><th>费用</th></tr></thead><tbody><tr><td>5 分钟视频分析</td><td>~300 次</td><td>~0.03 元</td></tr><tr><td>2 小时电影分析</td><td>~2000 次</td><td>~0.2 元</td></tr></tbody></table><hr><h2 id="edge-tts-配音合成" tabindex="-1">Edge TTS（配音合成） <a class="header-anchor" href="#edge-tts-配音合成" aria-label="Permalink to &quot;Edge TTS（配音合成）&quot;">​</a></h2><p><strong>免费使用，无需 API Key！</strong></p><p>微软官方 TTS 引擎，50+ 音色，支持中文。</p><h3 id="推荐音色" tabindex="-1">推荐音色 <a class="header-anchor" href="#推荐音色" aria-label="Permalink to &quot;推荐音色&quot;">​</a></h3><table tabindex="0"><thead><tr><th>音色 ID</th><th>名称</th><th>适用风格</th></tr></thead><tbody><tr><td>zh-CN-XiaoxiaoNeural</td><td>晓晓</td><td>治愈、浪漫、怀旧</td></tr><tr><td>zh-CN-YunxiNeural</td><td>云希</td><td>悬疑、励志</td></tr><tr><td>zh-CN-YunyangNeural</td><td>云扬</td><td>纪录片、正式</td></tr><tr><td>zh-CN-XiaoyiNeural</td><td>小艺</td><td>幽默、轻松</td></tr></tbody></table><h3 id="高级参数" tabindex="-1">高级参数 <a class="header-anchor" href="#高级参数" aria-label="Permalink to &quot;高级参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>范围</th><th>说明</th></tr></thead><tbody><tr><td>语速</td><td>0.5x – 2.0x</td><td>默认 1.0x</td></tr><tr><td>音调</td><td>-50% – +50%</td><td>默认 0</td></tr><tr><td>音量</td><td>-50% – +50%</td><td>默认 0</td></tr></tbody></table><hr><h2 id="f5-tts-音色克隆-可选" tabindex="-1">F5-TTS（音色克隆，可选） <a class="header-anchor" href="#f5-tts-音色克隆-可选" aria-label="Permalink to &quot;F5-TTS（音色克隆，可选）&quot;">​</a></h2><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> f5-tts</span></span></code></pre></div><h3 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h3><ol><li>准备参考音频（MP3/WAV，15–30 秒，说话清晰）</li><li>设置 → 配音配置 → F5-TTS → 上传参考音频</li><li>AI 自动克隆音色，后续配音使用克隆音色</li></ol><h3 id="费用" tabindex="-1">费用 <a class="header-anchor" href="#费用" aria-label="Permalink to &quot;费用&quot;">​</a></h3><p>完全本地运行，GPU 加速，无 API 费用。</p><hr><h2 id="一键配置" tabindex="-1">一键配置 <a class="header-anchor" href="#一键配置" aria-label="Permalink to &quot;一键配置&quot;">​</a></h2><p>在项目根目录创建 <code>.env</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># DeepSeek（解说稿生成）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEEPSEEK_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-xxx...xxxx</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 阿里云 Qwen3.7（视频分析）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DASHSCOPE_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-xxx...xxxx</span></span></code></pre></div><hr><h2 id="多服务商支持" tabindex="-1">多服务商支持 <a class="header-anchor" href="#多服务商支持" aria-label="Permalink to &quot;多服务商支持&quot;">​</a></h2><table tabindex="0"><thead><tr><th>服务</th><th>支持状态</th><th>说明</th></tr></thead><tbody><tr><td>DeepSeek</td><td>✅ 正式支持</td><td>推荐，性价比最高</td></tr><tr><td>OpenAI GPT-4</td><td>✅ 可配置</td><td>需自行修改端点</td></tr><tr><td>Qwen3.7</td><td>✅ 正式支持</td><td>视频理解必选</td></tr><tr><td>Edge TTS</td><td>✅ 内置免费</td><td>配音合成</td></tr><tr><td>F5-TTS</td><td>✅ 本地运行</td><td>音色克隆</td></tr></tbody></table><hr><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><h3 id="_401-unauthorized" tabindex="-1">401 Unauthorized <a class="header-anchor" href="#_401-unauthorized" aria-label="Permalink to &quot;401 Unauthorized&quot;">​</a></h3><p>API Key 无效或已过期，检查 Key 是否正确复制。</p><h3 id="_429-rate-limit" tabindex="-1">429 Rate Limit <a class="header-anchor" href="#_429-rate-limit" aria-label="Permalink to &quot;429 Rate Limit&quot;">​</a></h3><p>触发了 API 限流，1 分钟后重试，或在服务商控制台升级套餐。</p><h3 id="视频分析超时" tabindex="-1">视频分析超时 <a class="header-anchor" href="#视频分析超时" aria-label="Permalink to &quot;视频分析超时&quot;">​</a></h3><p>长视频（1 小时+）建议分段处理，或降低抽帧频率（设置 → AI 配置 → 抽帧间隔改为 2 秒）。</p>`,49)])])}const k=a(i,[["render",h]]);export{b as __pageData,k as default};
